#!/usr/bin/env bash\nset -e\n\n# Build the Docker image\nIMAGE_NAME="apocalypse-quote-test"\ndocker build -t $IMAGE_NAME .\n\n# Run the container with a known QUOTE value\nCONTAINER_ID=$(docker run -d -p 8081:8080 -e QUOTE="TestQuote" $IMAGE_NAME)\n# Give the server a moment to start\nsleep 1\n\n# Retrieve the response\nRESULT=$(curl -s http://localhost:8081)\n\n# Clean up\ndocker rm -f $CONTAINER_ID > /dev/null\ndocker rmi -f $IMAGE_NAME > /dev/null\n\n# Verify the output\nif [ "$RESULT" = "TestQuote" ]; then\n  echo "PASS"\n  exit 0\nelse\n  echo "FAIL: expected 'TestQuote' but got '$RESULT'"\n  exit 1\nfi\n
